  "material_tests": {
   "BPA": "杯体 Tritan 材料，有材料供应商的 BPA-free 声明，无成品第三方报告"
  },
  "moq_units": 1000,
  "fob_ningbo_usd": {
   "1000-4999": 6.2,
   "5000+": 5.7
  },
  "packaging": "color box, 40 units per carton",
  "selling_points_zh": [
   "USB-C 充电",
   "一键操作",
   "杯体分离时自动断电",
   "一次充电约 12 次（工厂内部测试）"
  ]
